6.2 紅葉フェノロジーの観測
次は紅葉です。このカメラが設置されている木曽駒岳周辺は紅葉の名所として知られており、秋にはロープウェイが大混雑します。一方、気候変動による紅葉の色づきの悪化も指摘されており（Koide et al. (2025)）、継続的なモニタリングが求められています。
紅葉の度合いは、Red Ratio(RR)で求めてみましょう。式はGRとほぼ同じで、相対的な赤色の強さを表します。
\[
RR = \frac{Red}{Red + Green + Blue}
\]
それではautumn_leaf.R という名前で新しいRスクリプトを作成し、以下を書き込みます。


library(terra)
library(tidyterra)
library(tidyverse)
library(patchwork)
library(lubridate)

# autumn_leaf.R

# 空のマスク画像
sky_mask &lt;- rast("sky.png") |&gt;
  mutate(sky = ifelse(sky &gt; 0, TRUE, FALSE)) # 空はTRUE, 空以外はFALSEにする

# 画像のパスを受け取り、Red ratioを返す関数
calculate_rr &lt;- function(image_path) {
  rr &lt;- image_path |&gt;
    rast() |&gt;
    flip() |&gt;
    colorize(to = "hsv") |&gt; # HSVに変換して戻すと、レイヤー名が勝手にred, green, blueになって便利
    colorize(to = "rgb") |&gt;
    mutate(rr = (red) / (red + green + blue)) |&gt;
    c(sky_mask) |&gt;
    mutate(rr = ifelse(sky, NA, rr)) |&gt;
    select(rr)

  return(rr)
}

# Red ratioをプロットする関数
plot_rr &lt;- function(rr) {
  ggplot() +
    geom_spatraster(data = rr) +
    theme(
      axis.text = element_blank()
    ) +
    scale_fill_gradient2(
      high = "firebrick1",
      low = "honeydew4",
      mid = "honeydew",
      midpoint = 0.4,
      limits = c(0, 0.8)
    )
}

# gokuraku_images/以下のJPEGファイル名のベクトルを取得。
images &lt;- tibble(
  files = list.files("gokuraku_images/", ".jpg", full.names = T)
) |&gt;
  mutate(date = ymd(files)) |&gt; # ファイル名から日付を取得
  mutate(month = month(date)) |&gt;
  filter(month &gt;= 9)

rrs &lt;- images |&gt;
  pull(files) |&gt;
  map(calculate_rr)
